// runParts: later parts only add (no overwriting or carving earlier parts' blocks), the ground stays writable,
// and blocks outside the palette are reported.
import { test } from "node:test";
import assert from "node:assert/strict";
import { Grid, runParts, shell, carve } from "../src/build.mjs";

const quiet = { log: () => {}, report: null };

test("a later part can't overwrite or carve an earlier part's wall, but can add beside it", () => {
  const g = new Grid([8, 6, 8]);
  const [r1, r2] = runParts(g, [
    ["shell", (v) => shell(v, [1, 0, 1], [6, 4, 6], "stone_bricks")],
    ["interior", (v) => { carve(v, [3, 1, 1], [3, 2, 1]); v.set(1, 2, 3, "glass"); v.set(3, 1, 3, "crafting_table"); }],
  ], quiet);
  assert.ok(r1.placed > 0 && r1.refused === 0);
  assert.equal(r2.refused, 3);
  assert.equal(r2.placed, 1);
  assert.equal(g.blockAt(3, 1, 1), "minecraft:stone_bricks");
  assert.equal(g.blockAt(1, 2, 3), "minecraft:stone_bricks");
  assert.equal(g.blockAt(3, 1, 3), "minecraft:crafting_table");
  assert.deepEqual(r2.refusedAt[0].slice(3), ["air", "stone_bricks"]);
});

test("the ground laid before runParts stays writable; a part may rework its own blocks", () => {
  const g = new Grid([4, 3, 4]);
  g.fill([0, 0, 0], [3, 0, 3], "grass_block");
  const [r] = runParts(g, [["garden", (v) => { v.set(1, 0, 1, "farmland"); v.set(1, 1, 1, "oak_log"); v.set(1, 1, 1, "wheat", { age: 7 }); }]], quiet);
  assert.equal(r.refused, 0);
  assert.equal(g.blockAt(1, 0, 1), "minecraft:farmland");
  assert.equal(g.blockAt(1, 1, 1), "minecraft:wheat");
});

test("blocks outside the palette are reported, roles and objects both count", () => {
  const g = new Grid([4, 3, 4]);
  const lines = [];
  const [r] = runParts(g, [["p", (v) => { v.set(0, 0, 0, "stone_bricks"); v.set(1, 0, 0, "lantern"); v.set(2, 0, 0, "pink_wool"); v.set(3, 0, 0, "pink_wool"); }]],
    { palette: { roles: { walls: ["stone_bricks"] }, objects: ["lantern"] }, log: (l) => lines.push(l), report: null });
  assert.deepEqual(r.offPalette, ["pink_wool x2"]);
  assert.match(lines[0], /OFF-PALETTE: pink_wool x2/);
});

test("layers draws blocks from rows of characters with a legend, layer by layer; unknown characters are skipped", async () => {
  const { layers } = await import("../src/build.mjs");
  const g = new Grid([5, 3, 3]);
  const n = layers(g, [1, 0, 0], { "#": "oak_planks", b: ["red_bed", { facing: "south", part: "head" }] }, [
    ["###", "#b.", "###"],
    ["#  "],
  ]);
  assert.equal(n, 9);
  assert.equal(g.blockAt(1, 0, 0), "minecraft:oak_planks");
  assert.equal(g.get(2, 0, 1).state.facing, "south");
  assert.equal(g.blockAt(3, 0, 1), "minecraft:air");
  assert.equal(g.blockAt(1, 1, 0), "minecraft:oak_planks");
  const [r] = runParts(new Grid([4, 2, 4]), [["p", (v) => layers(v, [0, 0, 0], { x: "stone" }, ["xx", "xx"])]], quiet);
  assert.equal(r.placed, 4);                                             // through runParts' view: counted and locked
});
